create extension if not exists pgcrypto;
create type public.app_role as enum ('member','pod_lead','account_manager','founder');
create type public.craft_type as enum ('writer','editor','designer','account_manager');
create type public.tier_type as enum ('intern','junior','standard','senior','lead');
create type public.chat_sender_role as enum ('client','yoso');
create type public.chat_message_type as enum ('text','voice','image','document');
create table public.pods(id uuid primary key default gen_random_uuid(),name text not null unique,lead_id uuid);
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,role public.app_role not null default 'member',pod_id uuid references public.pods(id));
alter table public.pods add constraint pods_lead_fk foreign key(lead_id) references public.profiles(id) on delete set null;
create table public.clients(id uuid primary key default gen_random_uuid(),name text not null,account_manager_id uuid references public.profiles(id),created_at timestamptz not null default now());
create table public.client_access(user_id uuid references public.profiles(id) on delete cascade,client_id uuid references public.clients(id) on delete cascade,primary key(user_id,client_id));
create table public.employees(id text primary key,name text not null,craft public.craft_type not null,tier public.tier_type not null,pod_id uuid references public.pods(id),weekly_hours numeric not null check(weekly_hours between 0 and 60),leave_weeks int[] not null default '{}');
create table public.deliverables(id text primary key,title text not null,client_id uuid references public.clients(id),craft public.craft_type not null,due_date date not null,estimated_hours numeric not null check(estimated_hours>0),week int not null check(week between 1 and 4),assigned_to text references public.employees(id),status text not null default 'open' check(status in ('open','assigned','done')),depends_on text[] not null default '{}',created_at timestamptz not null default now());
create table public.channels(id uuid primary key default gen_random_uuid(),name text not null,client_id uuid references public.clients(id),created_at timestamptz default now());
create table public.channel_members(channel_id uuid references public.channels(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,primary key(channel_id,user_id));
create table public.chat_messages(id uuid primary key default gen_random_uuid(),channel_id uuid references public.channels(id) on delete cascade,client_id uuid references public.clients(id) on delete cascade,sender_id uuid references public.profiles(id),sender_name text not null,sender_role public.chat_sender_role not null default 'yoso',type public.chat_message_type not null default 'text',text text not null default '',voice_path text,duration_seconds int check(duration_seconds between 1 and 120),idempotency_key text unique,sent_at timestamptz not null default now(),edited_at timestamptz,deleted_at timestamptz,search_vector tsvector generated always as (to_tsvector('simple',coalesce(text,'')||' '||coalesce(sender_name,''))) stored);
create index chat_messages_search_idx on public.chat_messages using gin(search_vector);
create index chat_messages_channel_time_idx on public.chat_messages(channel_id,sent_at desc);
create table public.message_reactions(id uuid primary key default gen_random_uuid(),message_id uuid references public.chat_messages(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,emoji text not null check(length(emoji)<=16),created_at timestamptz default now(),unique(message_id,user_id,emoji));
create table public.client_health_scores(id uuid primary key default gen_random_uuid(),client_id uuid references public.clients(id) on delete cascade,week_start date not null,score int not null check(score between 0 and 100),label text not null check(label in ('Healthy','Watch','At risk')),rule_version int not null default 1,signals jsonb not null default '[]',created_at timestamptz default now(),unique(client_id,week_start,rule_version));
create table public.health_alerts(id uuid primary key default gen_random_uuid(),client_id uuid references public.clients(id) on delete cascade,account_manager_id uuid references public.profiles(id),from_label text not null,to_label text not null,week_start date not null,rule_version int not null,created_at timestamptz default now(),unique(client_id,from_label,to_label,week_start,rule_version));
create or replace function public.current_role() returns public.app_role language sql stable security definer set search_path=public as $$ select role from public.profiles where id=auth.uid() $$;
create or replace function public.is_founder() returns boolean language sql stable security definer set search_path=public as $$ select coalesce(public.current_role()='founder',false) $$;
create or replace function public.can_read_channel(cid uuid) returns boolean language sql stable security definer set search_path=public as $$ select public.is_founder() or exists(select 1 from public.channel_members cm where cm.channel_id=cid and cm.user_id=auth.uid()) $$;
create or replace function public.can_read_client(cid uuid) returns boolean language sql stable security definer set search_path=public as $$ select public.is_founder() or exists(select 1 from public.clients c where c.id=cid and c.account_manager_id=auth.uid()) or exists(select 1 from public.client_access ca where ca.client_id=cid and ca.user_id=auth.uid()) or (public.current_role()='pod_lead' and exists(select 1 from public.profiles p join public.pods pod on pod.id=p.pod_id where p.id=auth.uid() and exists(select 1 from public.deliverables d join public.employees e on e.id=d.assigned_to where d.client_id=cid and e.pod_id=p.pod_id))) $$;
alter table public.pods enable row level security;alter table public.profiles enable row level security;alter table public.clients enable row level security;alter table public.client_access enable row level security;alter table public.employees enable row level security;alter table public.deliverables enable row level security;alter table public.channels enable row level security;alter table public.channel_members enable row level security;alter table public.chat_messages enable row level security;alter table public.message_reactions enable row level security;alter table public.client_health_scores enable row level security;alter table public.health_alerts enable row level security;
create policy profiles_read on public.profiles for select using(id=auth.uid() or public.is_founder() or (public.current_role()='pod_lead' and pod_id=(select pod_id from public.profiles where id=auth.uid())));
create policy pods_read on public.pods for select using(public.is_founder() or id=(select pod_id from public.profiles where id=auth.uid()));
create policy clients_read on public.clients for select using(public.can_read_client(id));
create policy client_access_read on public.client_access for select using(user_id=auth.uid() or public.is_founder());
create policy employees_read on public.employees for select using(public.is_founder() or id=auth.uid()::text or pod_id=(select pod_id from public.profiles where id=auth.uid()));
create policy deliverables_read on public.deliverables for select using(public.is_founder() or assigned_to=auth.uid()::text or exists(select 1 from public.employees e join public.profiles p on p.pod_id=e.pod_id where e.id=deliverables.assigned_to and p.id=auth.uid() and p.role='pod_lead') or public.can_read_client(client_id));
create policy channels_read on public.channels for select using(public.can_read_channel(id));
create policy channel_members_read on public.channel_members for select using(user_id=auth.uid() or public.is_founder() or public.can_read_channel(channel_id));
create policy chat_read on public.chat_messages for select using(public.can_read_channel(channel_id) and deleted_at is null);
create policy chat_insert on public.chat_messages for insert with check(public.can_read_channel(channel_id) and sender_id=auth.uid());
create policy chat_update on public.chat_messages for update using(public.can_read_channel(channel_id) and sender_id=auth.uid()) with check(public.can_read_channel(channel_id));
create policy reactions_read on public.message_reactions for select using(exists(select 1 from public.chat_messages m where m.id=message_id and public.can_read_channel(m.channel_id)));
create policy reactions_insert on public.message_reactions for insert with check(user_id=auth.uid() and exists(select 1 from public.chat_messages m where m.id=message_id and public.can_read_channel(m.channel_id)));
create policy reactions_delete on public.message_reactions for delete using(user_id=auth.uid() and exists(select 1 from public.chat_messages m where m.id=message_id and public.can_read_channel(m.channel_id)));
create policy health_read on public.client_health_scores for select using(public.can_read_client(client_id));
create policy alerts_read on public.health_alerts for select using(account_manager_id=auth.uid() or public.is_founder());
create policy employees_founder_write on public.employees for all using(public.is_founder()) with check(public.is_founder());
create policy deliverables_lead_write on public.deliverables for update using(public.is_founder() or exists(select 1 from public.profiles p join public.employees e on e.pod_id=p.pod_id where p.id=auth.uid() and p.role='pod_lead' and e.id=deliverables.assigned_to)) with check(public.is_founder() or exists(select 1 from public.profiles p join public.employees e on e.pod_id=p.pod_id where p.id=auth.uid() and p.role='pod_lead' and e.id=deliverables.assigned_to));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('voice-notes','voice-notes',false,10485760,array['audio/webm','audio/mp4','audio/mpeg','audio/ogg']) on conflict(id) do nothing;
create policy voice_read on storage.objects for select using(bucket_id='voice-notes' and public.can_read_channel((storage.foldername(name))[1]::uuid));
create policy voice_insert on storage.objects for insert with check(bucket_id='voice-notes' and public.can_read_channel((storage.foldername(name))[1]::uuid));
